options.validator:
// A subform row is identified by its fm_key, not by where it sits: an item
// under an item bundle is not a row of table_srr at all, so the position in the
// field path does not reach it. The row is found by walking the tree instead,
// falling back to position for a row the platform has not keyed yet.
const rowKey = arguments[0].field.split(".")[1];
const tableSRR = this.getValue("table_srr") || [];

const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);

const resolveRow = (key) => {
  for (const row of tableSRR) {
    if (row && String(row.fm_key) === String(key)) return row;

    for (const child of childrenOf(row || {})) {
      if (child && String(child.fm_key) === String(key)) return child;
    }
  }

  return tableSRR[key] || null;
};

const targetRow = resolveRow(rowKey) || {};
let toReturnedQty = targetRow.to_receive_qty;
const lineIndex = targetRow.line_index;
const hasParent = lineIndex ? String(lineIndex).split("-") : null;
let cummulativeReturnedQty = 0;

if (hasParent && hasParent.length > 1) {
  const parentLineIndex = parseInt(hasParent[0]);

  // The line this one sits under, found by the number it carries rather than by
  // counting rows. Matched on the whole label, not parsed: parseInt("1-1") is
  // also 1, so an item of the bundle would be found before the bundle itself.
  const parentRow = tableSRR.find(
    (item) => String(item.line_index) === hasParent[0],
  );

  toReturnedQty = parentRow ? parentRow.to_receive_qty : toReturnedQty;

  cummulativeReturnedQty = tableSRR.reduce((total, item) => {
    if (parseInt(item.parent_index) === parentLineIndex) {
      return total + (item.received_qty || 0);
    } else {
      return total;
    }
  }, 0);
}

console.log("toReturnedQty:", toReturnedQty);
console.log("cummulativeReturnedQty:", cummulativeReturnedQty);
if (cummulativeReturnedQty > toReturnedQty) {
  callback("Exceeds the returnable quantity");
} else {
  callback();
}

