const showStatusHTML = async (status) => {
  switch (status) {
    case "Draft":
      this.display(["draft_status"]);
      break;
    case "Completed":
      this.display(["completed_status"]);
      break;
  }
};

const disabledField = async (status) => {
  if (status !== "Draft") {
    this.disabled(
      [
        "contact_person",
        "received_date",
        "fileupload_ed0qx6ga",
        "table_srr",
        "input_y0dr1vke",
        "remarks",
      ],
      true,
    );

    this.hide(["button_save_as_draft", "button_completed"]);
  }
};

const setPlant = async (organizationId, pageStatus) => {
  const currentDept = this.getVarSystem("deptIds");

  if (currentDept === organizationId) {
    this.disabled("plant_id", false);
    this.disabled("table_srr", true);
  } else {
    if (pageStatus === "Add") {
      setTimeout(() => {
        this.setData({ plant_id: currentDept });
      }, 50);
    }
    this.disabled("plant_id", true);
  }
};

const displayManufacturingAndExpiredDate = async (status, pageStatus) => {
  const tableSRR = this.getValue("table_srr");
  if (pageStatus === "Edit") {
    if (status === "Draft") {
      walkTableSRR(tableSRR, (item, path) => {
        if (item.batch_no !== "-") {
          this.display([
            "table_srr.manufacturing_date",
            "table_srr.expired_date",
          ]);
        } else {
          this.disabled(
            [`${path}.manufacturing_date`, `${path}.expired_date`],
            true,
          );
        }
      });
    } else {
      walkTableSRR(tableSRR, (item) => {
        if (item.batch_no !== "-") {
          this.display([
            "table_srr.manufacturing_date",
            "table_srr.expired_date",
          ]);
        }
      });
    }
  } else {
    walkTableSRR(tableSRR, (item) => {
      if (item.batch_no !== "-") {
        this.display([
          "table_srr.manufacturing_date",
          "table_srr.expired_date",
        ]);
      }
    });
  }
};

const editSerialNumbers = async (tableSRR) => {
  walkTableSRR(tableSRR, (item, path) => {
    if (
      item.serial_numbers &&
      item.serial_numbers !== "" &&
      item.serial_numbers !== null
    ) {
      this.display(`table_srr.select_serial_number`);
      this.disabled(`${path}.received_qty`, true);
    } else {
      this.disabled(`${path}.received_qty`, false);
      this.disabled(`${path}.select_serial_number`, true);
    }
  });
};

// ===========================================================================
// ITEM BUNDLES
// ---------------------------------------------------------------------------
// table_srr is a tree: an item bundle is ONE row with the bundle's items under
// `children`. Those items are receiving lines in their own right -- batch
// managed, binned, serialised like any other -- and they are NOT rows of
// table_srr, so every pass below has to walk into them or they are set up as
// though they did not exist.
//
// The bundle row holds no stock: nothing is batched, binned or serialised
// against it. Its quantity is the number of bundles, which is what fixes its
// items' quantities, so their own field is not editable.
//
// Re-applied on reopen because editSerialNumbers enables received_qty on every
// row that has no serial numbers, which would otherwise unlock a bundle's items.
// ===========================================================================
const referenceId = (value) => {
  if (value && typeof value === "object") return value.id || null;
  return value || null;
};

const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);

// Every row of table_srr with the path it is addressed by. A subform row is
// identified by its fm_key, not by where it sits -- an item under a bundle is
// not a row of table_srr at all, so no index reaches it.
const walkTableSRR = (rows, visit) => {
  (rows || []).forEach((row, index) => {
    const path = row.fm_key ? `table_srr.${row.fm_key}` : `table_srr.${index}`;

    visit(row, path);

    childrenOf(row).forEach((child, childIndex) => {
      visit(
        child,
        child.fm_key
          ? `table_srr.${child.fm_key}`
          : `${path}.children.${childIndex}`,
      );
    });
  });
};

const applyBundleRowState = async () => {
  walkTableSRR(this.getValue("table_srr") || [], (row, path) => {
    const bundleId = referenceId(row.item_bundle_id);
    if (!bundleId) return;

    if (referenceId(row.material_id)) {
      this.disabled(`${path}.received_qty`, true);
      return;
    }

    this.disabled(
      [
        `${path}.batch_no`,
        `${path}.manufacturing_date`,
        `${path}.expired_date`,
        `${path}.location_id`,
        `${path}.storage_location_id`,
        `${path}.select_serial_number`,
      ],
      true,
    );
  });
};

const checkAccIntegrationType = async (organizationId) => {
  if (organizationId) {
    const resAI = await db
      .collection("accounting_integration")
      .where({ organization_id: organizationId })
      .get();

    if (resAI && resAI.data.length > 0) {
      const aiData = resAI.data[0];
      this.setData({ acc_integration_type: aiData.acc_integration_type });
    }
  }
};

const viewSerialNumbers = async (tableSRR) => {
  console.log("tableSRR", tableSRR);
  walkTableSRR(tableSRR, (item) => {
    if (
      item.serial_numbers &&
      item.serial_numbers !== "" &&
      item.serial_numbers !== null
    ) {
      this.display(`table_srr.serial_numbers`);
    }
  });
};

(async () => {
  try {
    const status = await this.getValue("srr_status");

    const pageStatus = this.isAdd
      ? "Add"
      : this.isEdit
        ? "Edit"
        : this.isView
          ? "View"
          : this.isCopy
            ? "Clone"
            : (() => {
                this.$message.error("Invalid page status");
              })();

    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    this.setData({ page_status: pageStatus });
    switch (pageStatus) {
      case "Add":
        this.display(["draft_status"]);
        this.setData({
          organization_id: organizationId,
          user_id: this.getVarGlobal("nickname"),
          received_date: new Date().toISOString().split("T")[0],
        });
        await setPlant(organizationId, pageStatus);
        await checkAccIntegrationType(organizationId);
        break;

      case "Edit":
        this.setData({ previous_status: status });
        await disabledField(status);
        await showStatusHTML(status);
        await checkAccIntegrationType(organizationId);
        await displayManufacturingAndExpiredDate(status, pageStatus);
        setTimeout(async () => {
          await editSerialNumbers(this.getValue("table_srr"));
        }, 200);
        // After editSerialNumbers, so a bundle's items stay locked to their
        // bundle rather than being re-enabled along with every other row.
        setTimeout(async () => {
          await applyBundleRowState();
        }, 250);

        break;

      case "View":
        this.hide(["button_save_as_draft", "button_completed"]);
        await showStatusHTML(status);
        await displayManufacturingAndExpiredDate(status, pageStatus);
        setTimeout(async () => {
          await viewSerialNumbers(this.getValue("table_srr"));
        }, 200);

        break;
    }
  } catch (error) {
    this.$message.error(error);
  }
})();

// An item bundle is one line with its items beneath it. Collapse those items on
// open so the document reads as a list of lines rather than of parts.
setTimeout(() => {
  this.getComponent("table_srr")?.hideChildRecord();
}, 100);

setTimeout(async () => {
  const maxRetries = 10;
  const interval = 500;
  for (let i = 0; i < maxRetries; i++) {
    const op = await this.onDropdownVisible(
      "srr_no_type",
      true,
    );
    if (op != null) break;
    await new Promise((resolve) => setTimeout(resolve, interval));
  }
  function getDefaultItem(arr) {
    return arr?.find((item) => item?.item?.is_default === 1);
  }
  var params = this.getComponent("srr_no");
  const { options } = params;

  const optionsData = this.getOptionData("srr_no_type") || [];
  const defaultData = getDefaultItem(optionsData);
  if (options?.canManualInput) {
    this.setOptionData("srr_no_type", [
      { label: "Manual Input", value: -9999 },
      ...optionsData,
    ]);
    if (this.isAdd) {
      this.setData({
        srr_no_type: defaultData ? defaultData.value : -9999,
      });
    }
  } else if (defaultData) {
    if (this.isAdd) {
      this.setData({ srr_no_type: defaultData.value });
    }
  }
}, 200);

const data = this.getValues();

// Get Sales Return IDs from arguments
const salesReturnIDs = arguments[0].value;

if (arguments[0].value) {
  this.setData({
    so_no_display: "",
    sr_no_display: "",
    table_srr: [],
  });
}

// Display SR numbers nicely
Promise.all(
  salesReturnIDs.map((srId) =>
    db
      .collection("sales_return")
      .doc(srId) // Direct document reference
      .get()
      .then((doc) => (doc ? doc.data[0].sales_return_no : null))
  )
).then((results) => {
  const displayText = results.filter(Boolean).join(", ");
  console.log("sr", results);
  this.setData({ sr_no_display: displayText });
});

// Check if salesReturnIDs is empty or invalid before proceeding
if (
  !salesReturnIDs ||
  (Array.isArray(salesReturnIDs) && salesReturnIDs.length === 0)
) {
  this.setData({ table_srr: [] });
  console.log("Sales Return IDs is empty, skipping processing");
  return;
}

// Additional validation check to make sure salesReturnIDs is an array
if (!Array.isArray(salesReturnIDs)) {
  console.error("Sales Return IDs is not an array:", salesReturnIDs);
  this.setData({ table_srr: [] });
  return;
}

// Fetch existing SRRs for these Sales Returns to calculate remaining quantities
const fetchExistingSRRs = async (salesReturnIDs) => {
  try {
    const srrPromises = salesReturnIDs.map((srId) =>
      db
        .collection("sales_return_receiving")
        .where({ sales_return_id: srId })
        .get()
    );

    const srrResults = await Promise.all(srrPromises);

    // Flatten and gather all SRR items
    let existingSrrItems = [];
    srrResults.forEach((result) => {
      if (result && result.data && result.data.length > 0) {
        result.data.forEach((srr) => {
          if (srr.table_srr && Array.isArray(srr.table_srr)) {
            existingSrrItems = [...existingSrrItems, ...srr.table_srr];
          }
        });
      }
    });

    console.log("Existing SRR items:", existingSrrItems);
    return existingSrrItems;
  } catch (error) {
    console.error("Error fetching existing SRRs:", error);
    return [];
  }
};

// Main processing function
(async () => {
  try {
    const existingSrrItems = await fetchExistingSRRs(salesReturnIDs);
    console.log("=== DEBUG: Existing SRR Items ===");
    console.log("existingSrrItems count:", existingSrrItems.length);

    let soNoArray = [];

    // DEBUG 2: Check each Sales Return query
    const promises = salesReturnIDs.map(async (salesReturnID, index) => {
      console.log(
        `\n=== DEBUG: Processing SR ${index + 1}/${salesReturnIDs.length} ===`
      );
      console.log("salesReturnID:", salesReturnID);

      try {
        const result = await db
          .collection("sales_return")
          .where({ id: salesReturnID })
          .get();

        // DEBUG 3: Check database query result
        console.log(`Raw result for ${salesReturnID}:`, result);
        console.log("Result type:", typeof result);
        console.log("Is array?", Array.isArray(result));
        console.log("Has data property?", result?.data !== undefined);

        // Your existing data extraction logic...
        let salesReturnData = null;

        if (Array.isArray(result) && result.length > 0) {
          salesReturnData = result[0];
        } else if (typeof result === "object" && result !== null) {
          if (result.data) {
            salesReturnData =
              Array.isArray(result.data) && result.data.length > 0
                ? result.data[0]
                : result.data;
          } else if (
            result.docs &&
            Array.isArray(result.docs) &&
            result.docs.length > 0
          ) {
            salesReturnData = result.docs[0].data
              ? result.docs[0].data()
              : result.docs[0];
          } else {
            salesReturnData = result;
          }
        }

        // DEBUG 4: Check extracted data
        console.log(
          `Extracted salesReturnData for ${salesReturnID}:`,
          salesReturnData
        );
        console.log("Has table_sr?", salesReturnData?.table_sr !== undefined);
        console.log(
          "table_sr is array?",
          Array.isArray(salesReturnData?.table_sr)
        );
        console.log("table_sr length:", salesReturnData?.table_sr?.length);

        const srrItems = [];

        if (salesReturnData && Array.isArray(salesReturnData.table_sr)) {
          soNoArray.push(salesReturnData.so_no_display);

          // DEBUG 5: Process each SR item
          console.log(
            `Processing ${salesReturnData.table_sr.length} items from SR ${salesReturnID}`
          );

          salesReturnData.table_sr.forEach((salesReturnItem, itemIndex) => {
            console.log(`\n--- Processing item ${itemIndex + 1} ---`);
            console.log("salesReturnItem:", salesReturnItem);
            console.log("Has material_id?", !!salesReturnItem.material_id);

            // Skip items without material ID
            if (!salesReturnItem.material_id) {
              console.log("❌ Skipping: No material_id");
              return;
            }

            // Calculate existing quantities
            const alreadyReceivedQty = existingSrrItems
              .filter(
                (item) =>
                  item.sr_number === salesReturnData.sales_return_no &&
                  item.material_id === salesReturnItem.material_id
              )
              .reduce(
                (total, item) => total + (Number(item.return_quantity) || 0),
                0
              );

            const expectedReturnQty =
              Number(salesReturnItem.expected_return_qty) || 0;
            const toReturnedQty = Math.max(
              0,
              expectedReturnQty - alreadyReceivedQty
            );

            console.log("Expected return qty:", expectedReturnQty);
            console.log("Already received qty:", alreadyReceivedQty);
            console.log("To be returned qty:", toReturnedQty);

            // If nothing left to receive, skip this item
            if (toReturnedQty <= 0) {
              console.log(
                "❌ Skipping: Nothing left to return (toReturnedQty <= 0)"
              );
              return;
            }

            console.log("✅ Adding item to srrItems");

            // Add to SRR items
            srrItems.push({
              sr_id: salesReturnID,
              sr_number: salesReturnData.sales_return_no,
              material_id: salesReturnItem.material_id,
              material_name: salesReturnItem.material_name,
              receiving_detail: salesReturnItem.material_desc,
              line_so_no: salesReturnItem.line_so_no,
              more_desc: salesReturnItem.more_desc || "",
              line_remark_1: salesReturnItem.line_remark_1 || "",
              line_remark_2: salesReturnItem.line_remark_2 || "",
              so_quantity: salesReturnItem.so_quantity,
              expected_return_qty: salesReturnItem.expected_return_qty,
              to_returned_qty: toReturnedQty,
              return_quantity: toReturnedQty,
              quantity_uom: salesReturnItem.quantity_uom,
              return_reason: salesReturnItem.return_reason,
              unit_price: salesReturnItem.unit_price,
              total_price: salesReturnItem.total_price,
              fifo_sequence: salesReturnItem.fifo_sequence,
              costing_method: "", // Will be set later
            });
          });
        } else {
          console.log("❌ No valid table_sr data found");
        }

        console.log(`Final srrItems for ${salesReturnID}:`, srrItems);
        console.log(`Items count: ${srrItems.length}`);

        return srrItems;
      } catch (error) {
        console.error(
          `❌ Error processing Sales Return ${salesReturnID}:`,
          error
        );
        return [];
      }
    });

    console.log("\n=== DEBUG: Waiting for all promises ===");
    const allSrrItemsArrays = await Promise.all(promises);
    console.log("All SRR items arrays:", allSrrItemsArrays);
    console.log("Arrays count:", allSrrItemsArrays.length);

    // Flatten the array
    const allSrrItems = allSrrItemsArrays.flat();
    console.log("\n=== DEBUG: Final Result ===");
    console.log("Final allSrrItems:", allSrrItems);
    console.log("Final count:", allSrrItems.length);

    const soNoDisplay = soNoArray.filter(Boolean).join(", ");

    this.setData({
      table_srr: allSrrItems,
      so_no_display: soNoDisplay,
    });

    if (allSrrItems.length === 0) {
      console.log(
        "🔍 SUMMARY: allSrrItems is empty. Check the debug logs above to see where items are being filtered out."
      );
    } else {
      console.log(
        `✅ SUCCESS: Processed ${allSrrItems.length} items from ${salesReturnIDs.length} Sales Returns`
      );
    }
  } catch (error) {
    console.error("❌ MAIN ERROR:", error);
    this.setData({ table_srr: [] });
  }
})();

// Save as Draft Button onClick Handler
const closeDialog = () => {
  if (this.parentGenerateForm) {
    this.parentGenerateForm.$refs.SuPageDialogRef.hide();
    this.parentGenerateForm.refresh();
    this.hideLoading();
  }
};

(async () => {
  this.showLoading("Saving Sales Return Receiving..");
  let data = this.getValues();
  data.srr_status = "Draft";
  data.filter_srr = "No";

  await this.runWorkflow(
    "2047250011014750209",
    {
      allData: data,
    },
    async (res) => {
      console.log("SR Data", res.data);
      this.$message.success("Sales Return Receiving saved successfully");
      closeDialog();
    },
    async (err) => {
      console.error(err);
      this.$message.error("Saving Sales Return Receiving failed");
      this.hideLoading();
      if (err.data?.code === 401) {
        // 401 - Mandatory fields missing

        await this.$alert(`${err.data?.msg}`, "", {
          confirmButtonText: "OK",
          type: "error",
          dangerouslyUseHTMLString: true,
        });
      }
    },
  );
})();

const rowIndex = arguments[0].rowIndex;
const rows = this.getValue("table_srr") || [];

// A row is addressed by its fm_key: the platform resolves
// `table_srr.<fm_key>.<field>` to that row wherever it sits. table_srr is a
// tree -- an item under an item bundle is not a row of table_srr at all -- so
// the key is the only thing that reaches it, and a position goes stale the
// moment a row above it is removed. The event carries the row it fired on;
// position is the fallback for a row the platform has not keyed yet.
const rowKey =
  (arguments[0].row && arguments[0].row.fm_key) ||
  (rows[rowIndex] || {}).fm_key ||
  rowIndex;
const rowPath = `table_srr.${rowKey}`;

const costing_method = arguments[0]?.fieldModel.item.material_costing_method;
this.setData({
  [`${rowPath}.costing_method`]: costing_method
})

const targetLocation = arguments[0]?.fieldModel?.item.location_id;
const batchManagement = arguments[0]?.fieldModel?.item.item_batch_management;

if(batchManagement === 1){
  this.disabled(`${rowPath}.batch_id`,false)
} else {
  this.disabled(`${rowPath}.batch_id`,true)
}
if(!targetLocation){
  const plantId = this.getValue('plant_id');
  db.collection('bin_location').where({
    plant_id: plantId,
    is_default: true
  }).get().then((resBinLocation) => {
    if(resBinLocation.data.length > 0){
    this.setData({[`${rowPath}.location_id`]: resBinLocation.data[0].id}); 
    }
  })
}

const closeDialog = () => {
  if (this.parentGenerateForm) {
    this.parentGenerateForm.$refs.SuPageDialogRef.hide();
    this.parentGenerateForm.refresh();
    this.hideLoading();
  }
};

const submitForm = async (data) => {
  await this.runWorkflow(
    "2047250011014750209",
    {
      allData: data,
    },
    (res) => {
      this.$message.success(`${this.isEdit ? "Update" : "Add"} successfully`);
      closeDialog();
    },
    async (error) => {
      this.hideLoading();
      console.error(error);
      if (
        error.data?.code === 401 ||
        error.data?.code === 402 ||
        error.data?.code === 403 ||
        error.data?.code === 405 ||
        error.data?.code === 406 ||
        error.data?.code === 407
      ) {
        // 401 - Mandatory fields missing
        // 402 - Available Return Qty < Return Qty
        // 403 - Total return qty == 0
