const fetchItemData = async (itemID) => {
  const resItem = await db
    .collection("Item")
    .field("item_batch_management,batch_number_genaration,table_default_bin")
    .where({ id: itemID })
    .get();

  if (!resItem || resItem.data.length === 0) return;
  else return resItem.data[0];
