// ===========================================================================
// ITEM BUNDLES
// ---------------------------------------------------------------------------
// An item bundle is ONE line on the sales return with the bundle's items
// beneath it, and it is received as a whole.
//
// table_srr is a TREE: the bundle is ONE row with its items under `children`,
// the same shape table_sr and table_gd hold.
//
// The bundle row holds no stock -- nothing is batched, binned or serialised
// against it, and its quantity is the number of bundles -- so it also carries
// has_child = 1, which is what the save workflow's "IF no Child" gate reads.
//
// It is still a line of the return in its own right, with its own received
// quantity to advance: without it the return's bundle line never closes and the
// document stays Partially Received forever.
//
// The rows are BUILT flat and nested at the end, because one return line
// already becomes several receiving rows on the way here -- applySourceBatches
// splits a line into one row per source batch -- and that has to happen to a
// bundle's items too, before they are hung under their bundle.
// ===========================================================================
const referenceId = (value) => {
  if (value && typeof value === "object") return value.id || null;
  return value || null;
};

const childrenOf = (row) => (Array.isArray(row.children) ? row.children : []);

// A line read off the return carries `material_id`; an entry off the picker
// carries the joined item as `item`. Both shapes reach here, and a bundle line
// is the one holding neither.
const isBundleParentRow = (row) =>
  Boolean(referenceId(row.item_bundle_id)) &&
  !referenceId(row.material_id) &&
  !referenceId(row.item);

// A return's lines arrive as one array whose bundles may be nested or flat.
// Three ways a child points back at its parent are handled, because which one
// is present depends on where the rows came from:
//
//   1. already nested under `children`, which is how the return stores them
//   2. parent_id / parent_fm_key on the child row
//   3. neither -- a bundle row followed by its item rows, which is what a tree
//      looks like once it has been flattened and lost its links
const groupBundleRows = (rows) => {
  const childIndexes = new Map();
  const claimed = new Set();

  const isBundleItem = (row) =>
    Boolean(referenceId(row.item_bundle_id)) &&
    Boolean(referenceId(row.material_id));

  let openParent = null;

  rows.forEach((row, index) => {
    if (isBundleParentRow(row)) {
      if (childrenOf(row).length > 0) {
        openParent = null; // already a tree: nothing to reattach
        return;
      }

      childIndexes.set(index, []);
      openParent = index;
      return;
    }

    if (!isBundleItem(row)) {
      openParent = null; // a plain line closes the bundle above it
      return;
    }

    let parentIndex = null;

    rows.forEach((candidate, candidateIndex) => {
      if (parentIndex !== null || !childIndexes.has(candidateIndex)) return;

      const byId =
        row.parent_id != null &&
        candidate.id != null &&
        String(row.parent_id) === String(candidate.id);
      const byKey =
        row.parent_fm_key != null &&
        candidate.fm_key != null &&
        String(row.parent_fm_key) === String(candidate.fm_key);

      if (byId || byKey) parentIndex = candidateIndex;
    });

    if (
      parentIndex === null &&
      openParent !== null &&
      String(referenceId(rows[openParent].item_bundle_id)) ===
        String(referenceId(row.item_bundle_id))
    ) {
      parentIndex = openParent;
    }

    if (parentIndex === null) return; // orphan: kept as a line of its own

    childIndexes.get(parentIndex).push(index);
    claimed.add(index);
  });

  return { childIndexes, claimed };
};

// Every line of the return, once, with each bundle's items directly after their
// bundle -- whichever of the three shapes above it arrived in.
const flattenSRLines = (rows) => {
  const { childIndexes, claimed } = groupBundleRows(rows || []);
  const flat = [];

  (rows || []).forEach((row, index) => {
    if (claimed.has(index)) return; // already emitted under its bundle

    flat.push(row);

    const nested = childrenOf(row);
    const regrouped = (childIndexes.get(index) || []).map(
      (childIndex) => rows[childIndex],
    );

    for (const child of nested.length > 0 ? nested : regrouped) {
      flat.push(child);
    }
  });

  console.log("item bundle grouping", {
    rows: (rows || []).length,
    lines: flat.length,
  });

  return flat;
};

// Flat rows back into a tree: a bundle row followed by its items becomes ONE
// row with those items under `children`.
const nestRows = (rows) => {
  const tree = [];
  let openBundle = null;

  for (const row of rows) {
    const bundleId = referenceId(row.item_bundle_id);

    if (bundleId && !referenceId(row.material_id)) {
      const parent = { ...row, children: [] };
      tree.push(parent);
      openBundle = {
        row: parent,
        bundleId: String(bundleId),
        srId: String(row.sr_id),
      };
      continue;
    }

    if (
      bundleId &&
      openBundle &&
      openBundle.bundleId === String(bundleId) &&
      openBundle.srId === String(row.sr_id)
    ) {
      openBundle.row.children.push(row);
      continue;
    }

    openBundle = null;
    tree.push(row);
  }

  return tree;
};

// The "No" column the user reads. A bundle's items are numbered INSIDE their
// bundle -- 1, 1-1, 1-2, 2 -- which is the convention the sales return and the
// sales invoice already use for them.
const numberLines = (rows) => {
  rows.forEach((row, index) => {
    row.line_index = String(index + 1);

    childrenOf(row).forEach((child, childIndex) => {
      child.line_index = `${index + 1}-${childIndex + 1}`;
    });
  });

  return rows;
};

// Every row of table_srr with the path it is addressed by. A subform row is
// identified by its fm_key, not by where it sits -- an item under a bundle is
// not a row of table_srr at all, so no index reaches it.
const walkTableSRR = (rows, visit) => {
  (rows || []).forEach((row, index) => {
    const path = row.fm_key ? `table_srr.${row.fm_key}` : `table_srr.${index}`;

    visit(row, path);

    childrenOf(row).forEach((child, childIndex) => {
      visit(
        child,
        child.fm_key
          ? `table_srr.${child.fm_key}`
          : `${path}.children.${childIndex}`,
      );
    });
  });
};

// A bundle's items follow the number of bundles typed on the line above them,
// so their own quantity is not editable, and nothing is batched, binned or
// serialised against the bundle line itself. Everything else is untouched.
const applyRowState = async () => {
  walkTableSRR(this.getValue("table_srr") || [], (row, path) => {
    const bundleId = referenceId(row.item_bundle_id);
    if (!bundleId) return;

    if (referenceId(row.material_id)) {
      this.disabled(`${path}.received_qty`, true);
      return;
    }

    this.disabled(
      [
        `${path}.batch_no`,
        `${path}.manufacturing_date`,
        `${path}.expired_date`,
        `${path}.location_id`,
        `${path}.storage_location_id`,
        `${path}.select_serial_number`,
        `${path}.inventory_category`,
      ],
      true,
    );
  });

  // An item bundle is one line with its items beneath it. Collapse those items
  // so the document reads as a list of lines rather than of parts.
  this.getComponent("table_srr")?.hideChildRecord();
};

// Item master default bin for this plant. Takes priority over the plant-level
// default; a row without a bin is treated as unconfigured so we never stamp a
// blank bin on the line.
const getItemDefaultBin = (tableDefaultBin, plantId) => {
  if (!plantId || !Array.isArray(tableDefaultBin)) return null;

  const matchingBin = tableDefaultBin.find(
    (bin) => bin.plant_id === plantId && bin.bin_location,
  );

  if (!matchingBin) return null;

  return {
    binLocation: matchingBin.bin_location,
    storageLocation: matchingBin.storage_location || null,
  };
};

// Where a line is received into. A bin belongs to a storage location, so the
// two are always taken from the SAME source: the item master's default for this
// plant when it has one, and the plant's own pair otherwise -- which is what
// onChange_plant resolved, the bin being looked up inside that storage location.
//
// Both columns are required on table_srr, so neither may be left unset. Before
// this, a line falling back to the plant's bin was given no storage location at
// all and could not be saved.
const receivingLocation = (
  itemDefaultBin,
  defaultBin,
  defaultStorage,
  isBundleLine,
) => {
  // A bundle line holds no stock: nothing is ever received into a bin against
  // it, so it is given neither. Both fields are disabled on that row, so the
  // required rule does not fire on them. Blank rather than null -- these are
  // id-typed columns, and a null comes back as 数据转换BigInt类型失败.
  if (isBundleLine) {
    return { location_id: "", storage_location_id: "" };
  }

  if (itemDefaultBin?.binLocation) {
    return {
      location_id: itemDefaultBin.binLocation,
      // An item master default bin recorded without its storage location falls
      // back to the plant's, rather than leaving a required field empty.
      storage_location_id: itemDefaultBin.storageLocation || defaultStorage,
    };
  }

  return {
    location_id: defaultBin,
    storage_location_id: defaultStorage,
  };
};

// `temp_qty_data` is the balance breakdown the delivery was picked from, so it
// records which batch every delivered unit came out of.
const parseTempQtyData = (raw) => {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;

  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (error) {
    return [];
  }
};

const sourceBatchesOf = (tempQtyData) => {
  const byBatch = new Map();

  for (const entry of parseTempQtyData(tempQtyData)) {
    if (!entry.batch_id) continue;

    const qty = parseFloat(
      entry.gd_quantity ??
        entry.unrestricted_qty ??
        entry.balance_quantity ??
        0,
    );
    if (!(qty > 0)) continue;

    const existing = byBatch.get(entry.batch_id);
    if (existing) existing.qty += qty;
    else byBatch.set(entry.batch_id, { batch_id: entry.batch_id, qty });
  }

  return [...byBatch.values()];
};

const fetchBatchNumbers = async (batchIds) => {
  if (batchIds.length === 0) return new Map();

  const resBatch = await db
    .collection("batch")
    .filter(new Filter().in("id", batchIds).build())
    .get();

  return new Map(
    (resBatch?.data || []).map((batch) => [batch.id, batch.batch_number]),
  );
};

// Qty already put back per (SR line, batch), so a second receipt does not
// return stock into a batch that earlier receipts already filled.
const fetchReceivedByBatch = async (srLineIds) => {
  const received = new Map();
  if (srLineIds.length === 0) return received;

  const resSRRLine = await db
    .collection("sales_return_receiving_05z4r94a_sub")
    .filter(new Filter().in("sr_line_id", srLineIds).build())
    .get();

  for (const line of resSRRLine?.data || []) {
    if (!line.batch_id) continue;

    const key = `${line.sr_line_id}|${line.batch_id}`;
    received.set(
      key,
      (received.get(key) || 0) + parseFloat(line.received_qty || 0),
    );
  }

  return received;
};

// sales_return_setup.generate_new_batch = 0 means the plant returns stock into
// the batch it was delivered from, so the row must carry that batch_id instead
// of a placeholder the save workflow would turn into a brand new batch. A line
// delivered out of several batches becomes one row per batch.
const applySourceBatches = async (rows, sourceMeta) => {
  const batchesPerRow = rows.map((row, index) =>
    row.batch_no === "-" ? [] : sourceBatchesOf(sourceMeta[index]),
  );

  const unresolved = [
    ...new Set(
      rows
        .filter(
          (row, index) =>
            row.batch_no !== "-" && batchesPerRow[index].length === 0,
        )
        .map((row) => row.material_name),
    ),
  ];

  if (unresolved.length > 0) {
    return {
      rows: null,
      error: `This plant returns stock into the batch it was delivered from, but no delivered batch could be found for:<br><br>${unresolved.join(
        "<br>",
      )}<br><br>Please check the goods delivery of these item(s) before receiving them.`,
    };
  }

  const multiBatchSRLineIds = [
    ...new Set(
      rows
        .filter((_row, index) => batchesPerRow[index].length > 1)
        .map((row) => row.sr_line_id)
        .filter(Boolean),
    ),
  ];

  const [batchNumberById, receivedByBatch] = await Promise.all([
    fetchBatchNumbers([
      ...new Set(batchesPerRow.flat().map((batch) => batch.batch_id)),
    ]),
    fetchReceivedByBatch(multiBatchSRLineIds),
  ]);

  const expanded = [];

  rows.forEach((row, index) => {
    const batches = batchesPerRow[index];

    if (batches.length === 0) {
      expanded.push(row);
      return;
    }

    if (batches.length === 1) {
      expanded.push({
        ...row,
        batch_id: batches[0].batch_id,
        batch_no: batchNumberById.get(batches[0].batch_id) || row.batch_no,
      });
      return;
    }

    let outstanding = parseFloat(row.to_receive_qty || 0);
    const rowsForLine = [];

    for (const batch of batches) {
      if (!(outstanding > 0)) break;

      const available =
        batch.qty -
        (receivedByBatch.get(`${row.sr_line_id}|${batch.batch_id}`) || 0);
      if (!(available > 0)) continue;

      const share = Math.min(available, outstanding);
      outstanding -= share;

      rowsForLine.push({
        ...row,
        batch_id: batch.batch_id,
        batch_no: batchNumberById.get(batch.batch_id) || row.batch_no,
        to_receive_qty: share,
      });
    }

    // Anything the source batches cannot account for still has to be
    // receivable, so it stays on the first batch rather than disappearing.
    if (outstanding > 0) {
      if (rowsForLine.length === 0) {
        rowsForLine.push({
          ...row,
          batch_id: batches[0].batch_id,
          batch_no: batchNumberById.get(batches[0].batch_id) || row.batch_no,
        });
      } else {
        rowsForLine[0].to_receive_qty += outstanding;
      }
    }

    expanded.push(...rowsForLine);
  });

  return { rows: expanded, error: null };
};

