(async () => {
  const referenceType = arguments[0].referenceType;
  const currentItemArray = arguments[0].itemArray;
  let existingSRR = this.getValue("table_srr");
  const previousReferenceType = this.getValue("reference_type");
  const defaultBinLocation = this.getValue("default_bin_location");
  const defaultStorageLocation = this.getValue("default_storage_location");
  const plantId = this.getValue("plant_id");
  const newBatch = this.getValue("new_batch");

  let tableSRR = [];
  let sourceMeta = [];
  let salesReturnNumber = [];
  let srId = [];
  let salesOrderNumber = [];
  let soId = [];
  let goodsDeliveryNumber = [];
  let gdId = [];

  if (currentItemArray.length === 0) {
    this.$alert("Please select at least one sales return / item.", "Error", {
      confirmButtonText: "OK",
      type: "error",
    });

    return;
  }

  if (previousReferenceType && previousReferenceType !== referenceType) {
    await this.$confirm(
      `You've selected a different reference type than previously used. <br><br>Current Reference Type: ${referenceType} <br>Previous Reference Type: ${previousReferenceType} <br><br>Switching will <strong>reset all items</strong> in this document. Do you want to proceed?`,
      "Different Reference Type Detected",
      {
        confirmButtonText: "Proceed",
        cancelButtonText: "Cancel",
        type: "error",
        dangerouslyUseHTMLString: true,
      },
    ).catch(() => {
      console.log("User clicked Cancel or closed the dialog");
      throw new Error();
    });

    existingSRR = [];
  }

  const uniqueCustomers = new Set(
    currentItemArray.map((srr) => srr.customer_id),
  );
  const allSameCustomer = uniqueCustomers.size === 1;

  if (!allSameCustomer) {
    this.$alert(
      "Received returned item(s) from more than two different customers is not allowed.",
      "Error",
      {
        confirmButtonText: "OK",
        type: "error",
      },
    );
    return;
  }

  this.closeDialog("dialog_select_item");
  this.showLoading();

  // "Item" reference builds its lines straight from the dialog rows without an
  // item fetch. Reuse the subform the row already carries and resolve only the
  // ones missing it, in ONE batched fetch.
  const defaultBinByItem = new Map();

  if (referenceType === "Item") {
    const missingItemIds = [];

    // A bundle entry carries its items on it, and they need a bin like any
    // other line. The bundle line itself has no item, so it drops out here.
    for (const srItem of currentItemArray.flatMap((entry) => [
      entry,
      ...childrenOf(entry),
    ])) {
      const itemId = srItem.item?.id;
      if (!itemId || defaultBinByItem.has(itemId)) continue;

      if (Array.isArray(srItem.item.table_default_bin)) {
        defaultBinByItem.set(itemId, srItem.item.table_default_bin);
      } else if (!missingItemIds.includes(itemId)) {
        missingItemIds.push(itemId);
      }
    }

    if (missingItemIds.length > 0) {
      const resItems = await db
        .collection("Item")
        .filter(new Filter().in("id", missingItemIds).build())
        .get();

      for (const item of resItems?.data || []) {
        defaultBinByItem.set(item.id, item.table_default_bin);
      }
    }
  }

  switch (referenceType) {
    case "Document":
      for (const sr of currentItemArray) {
        for (const srItem of flattenSRLines(sr.table_sr)) {
          let batchNo = "-";
          let itemDefaultBin = null;
          // Fetch item data to check batch management
          if (srItem.material_id) {
            const itemData = await fetchItemData(srItem.material_id);

            itemDefaultBin = getItemDefaultBin(
              itemData?.table_default_bin,
              plantId,
            );

            if (itemData && itemData.item_batch_management === 1) {
              if (
                itemData.batch_number_genaration ===
                "According To System Settings"
              ) {
                batchNo = "Auto-generated batch number";
              } else {
                batchNo = "";
              }
            }
          }
          const isBundleLine = isBundleParentRow(srItem);

          const newtableSRRRecord = {
            material_id: srItem.material_id,
            material_name: srItem.material_name,
            receiving_detail: srItem.material_desc,
            more_desc: srItem.more_desc || "",
            sr_number: sr.sales_return_no,
            gd_number: srItem.gd_number,
            so_number: srItem.line_so_no,
            so_quantity: srItem.so_quantity,
            gd_quantity: srItem.good_delivery_qty,
            expected_return_qty: srItem.expected_return_qty,
            to_receive_qty: srItem.expected_return_qty - srItem.received_qty,
            quantity_uom: srItem.quantity_uom,
            return_reason: srItem.return_reason,

            sr_id: sr.sales_return_id,
            gd_id: srItem.gd_id,
            so_id: srItem.so_id,
            sr_line_id: srItem.id,
            gd_line_id: srItem.gd_line_id,
            so_line_id: srItem.so_line_id,
            item_category_id: srItem.item_category_id,

            unit_price: srItem.unit_price,
            total_price: srItem.total_price,

            line_remark_1: srItem.line_remark_1 || "",
            line_remark_2: srItem.line_remark_2 || "",

            fifo_sequence: srItem.fifo_sequence,
            costing_method: srItem.costing_method,
            ...receivingLocation(
              itemDefaultBin,
              defaultBinLocation,
              defaultStorageLocation,
              isBundleLine,
            ),
            batch_no: batchNo,
            // A bundle line holds no stock, so it belongs to no inventory
            // category. The field is disabled on that row.
            inventory_category: isBundleLine ? "" : "Unrestricted",
            serial_numbers: srItem.temp_qty_data,
            item_bundle_id: referenceId(srItem.item_bundle_id) || "",
            // A bundle line holds no stock: the save workflow's inventory loop
            // skips any row carrying this.
            ...(isBundleLine ? { has_child: 1 } : {}),
          };

          tableSRR.push(newtableSRRRecord);
          sourceMeta.push(srItem.temp_qty_data);
        }
      }

      break;

    case "Item":
      // A bundle entry stands for the bundle line and every item under it, so
      // it becomes that many rows -- the bundle first, its items after it.
      for (const srItem of currentItemArray.flatMap((entry) => [
        entry,
        ...childrenOf(entry),
      ])) {
        const itemDefaultBin = getItemDefaultBin(
          defaultBinByItem.get(srItem.item?.id),
          plantId,
        );

        const isBundleLine = isBundleParentRow(srItem);

        // A bundle line has no item, no unit of measure and no price of its
        // own, so every reference is read with ?. -- a plain dereference throws
        // on it before the bundle is ever added, and an entry with no item
        // reaches the save as a blank material id, which the server rejects
        // with a BigInt conversion error.
        const newtableSRRRecord = {
          material_id: srItem.item?.id || null,
          // A bundle line has no item to take a name from; the entry carries
          // the bundle's own name instead.
          material_name: srItem.item?.material_name || srItem.material_name,
          receiving_detail: srItem.material_desc,
          more_desc: srItem.more_desc || "",
          sr_number: srItem.sales_return_id?.sales_return_no,
          gd_number: srItem.goods_delivery_id?.delivery_no,
          so_number: srItem.sales_order_id?.so_no,
          so_quantity: srItem.so_quantity,
          gd_quantity: srItem.good_delivery_qty,
          expected_return_qty: srItem.expected_return_qty,
          to_receive_qty: srItem.expected_return_qty - srItem.received_qty,
          quantity_uom: srItem.quantity_uom,
          return_reason: srItem.return_reason,

          sr_id: referenceId(srItem.sales_return_id),
          gd_id: referenceId(srItem.goods_delivery_id),
          so_id: referenceId(srItem.sales_order_id),
          sr_line_id: srItem.sales_return_line_id,
          gd_line_id: referenceId(srItem.goods_delivery_line_id),
          so_line_id: referenceId(srItem.sales_order_line_id),
          item_category_id: srItem.item?.item_category,

          unit_price: srItem.unit_price,
          total_price: srItem.total_price,

          line_remark_1: srItem.line_remark_1 || "",
          line_remark_2: srItem.line_remark_2 || "",

          fifo_sequence: srItem.fifo_sequence,
          costing_method: srItem.costing_method,
          ...receivingLocation(
            itemDefaultBin,
            defaultBinLocation,
            defaultStorageLocation,
            isBundleLine,
          ),
          batch_no:
            srItem.item?.item_batch_management === 1
              ? srItem.item.batch_number_genaration ===
                "According To System Settings"
                ? "Auto-generated batch number"
                : ""
              : "-",
          // A bundle line holds no stock, so it belongs to no inventory
          // category. The field is disabled on that row.
          inventory_category: isBundleLine ? "" : "Unrestricted",
          serial_numbers: srItem.temp_qty_data,
          item_bundle_id: referenceId(srItem.item_bundle_id) || "",
          // A bundle line holds no stock: the save workflow's inventory loop
          // skips any row carrying this.
          ...(isBundleLine ? { has_child: 1 } : {}),
        };

        tableSRR.push(newtableSRRRecord);
        sourceMeta.push(srItem.temp_qty_data);
      }
      break;
  }

  // Filtered with the source breakdown alongside it so the two stay aligned.
  //
  // A bundle is kept or dropped as a WHOLE, decided by its bundle line: its
  // items are not lines the user picked and must never be left standing
  // without the line that fixes their quantity.
  const keptSourceMeta = [];
  let openBundle = null;

  const keepsOnItsOwn = (srr) =>
    srr.to_receive_qty !== 0 &&
    !existingSRR.find((srrItem) => srrItem.sr_line_id === srr.sr_line_id);

  tableSRR = tableSRR.filter((srr, index) => {
    const bundleId = referenceId(srr.item_bundle_id);
    let keep;

    if (bundleId && !srr.material_id) {
      keep = keepsOnItsOwn(srr);
      openBundle = {
        bundleId: String(bundleId),
        srId: String(srr.sr_id),
        keep: keep,
      };
    } else if (
      bundleId &&
      openBundle &&
      openBundle.bundleId === String(bundleId) &&
      openBundle.srId === String(srr.sr_id)
    ) {
      keep = openBundle.keep;
    } else {
      openBundle = null;
      keep = keepsOnItsOwn(srr);
    }

    if (keep) keptSourceMeta.push(sourceMeta[index]);
    return keep;
  });

  if (newBatch === 0) {
    const resolved = await applySourceBatches(tableSRR, keptSourceMeta);

    if (resolved.error) {
      this.hideLoading();
      this.$alert(resolved.error, "Missing Source Batch", {
        confirmButtonText: "OK",
        type: "error",
        dangerouslyUseHTMLString: true,
      });
      return;
    }

    tableSRR = resolved.rows;
  }

  // Flattened first so a bundle reopened from the database -- where its items
  // are rows in their own right, linked by parent_id -- is regrouped the same
  // way a freshly picked one is.
  const latesttableSRR = numberLines(
    nestRows(flattenSRLines([...existingSRR, ...tableSRR])),
  );
  console.log("latesttableSRR", latesttableSRR);

  // A bundle's items carry their own sales order line, and it is not always the
  // bundle's -- so the header roll-ups are taken over every line of the tree,
  // not just the rows of table_srr.
  const flatSRR = latesttableSRR.flatMap((srr) => [srr, ...childrenOf(srr)]);

  soId = [...new Set(flatSRR.map((srr) => srr.so_id))];
  salesOrderNumber = [...new Set(flatSRR.map((srr) => srr.so_number))];
  srId = [...new Set(flatSRR.map((srr) => srr.sr_id))];
  salesReturnNumber = [...new Set(flatSRR.map((srr) => srr.sr_number))];
  gdId = [...new Set(flatSRR.map((srr) => srr.gd_id))];
  goodsDeliveryNumber = [...new Set(flatSRR.map((srr) => srr.gd_number))];

  await this.setData({
    customer_id: currentItemArray[0].customer_id,
    table_srr: latesttableSRR,
    so_no_display: salesOrderNumber.join(", "),
    so_id: soId,
    sr_no_display: salesReturnNumber.join(", "),
    sr_id: srId,
    gd_no_display: goodsDeliveryNumber.join(", "),
    gd_id: gdId,
    reference_type: referenceType,
  });

  // Read back rather than reusing latesttableSRR: setData is what gives each
  // row its fm_key, and that key is how a row is addressed from here on.
  // Read back rather than reusing latesttableSRR: setData is what gives each
  // row its fm_key, and that key is how a row is addressed from here on. Walked
  // as a tree, because a bundle's items are batch-managed and serialised like
  // any other line and are not rows of table_srr.
  setTimeout(async () => {
    walkTableSRR(this.getValue("table_srr") || [], (item, path) => {
      if (item.batch_no !== "-") {
        this.display([
          "table_srr.manufacturing_date",
          "table_srr.expired_date",
        ]);
        if (item.batch_no === "") {
          this.disabled(`${path}.batch_no`, false);
        }
      } else {
        this.disabled(
          [`${path}.manufacturing_date`, `${path}.expired_date`],
          true,
        );
      }
    });
  }, 50);
  setTimeout(async () => {
    const pending = [];

    walkTableSRR(this.getValue("table_srr") || [], (item, path) => {
      if (item.serial_numbers) pending.push({ item: item, path: path });
    });

    for (const entry of pending) {
      await checkSerialNumber(
        JSON.parse(entry.item.serial_numbers),
        entry.path,
      );
    }
  }, 100);

  // Last, so it is not undone: checkSerialNumber re-enables received_qty on a
  // row with no serials, and a bundle's items must stay locked to their bundle.
  setTimeout(async () => {
    await applyRowState();
  }, 150);

  this.hideLoading();
})();

