(async () => {
  setTimeout(() => {
    (async () => {
      let tableSRR = await this.getValue("table_srr");
      console.log("tableSRR", tableSRR);

      // =====================================================================
      // ITEM BUNDLES
      // ---------------------------------------------------------------------
      // table_srr is a tree: an item bundle is ONE row with the bundle's items
      // under `children`. Removing the bundle row takes its items with it,
      // because they are not rows of table_srr -- there is nothing to strand.
      //
      // A bundle reopened from the database is another matter: it comes back
      // FLAT, its items rows in their own right, and each of them can be
      // removed on its own. A bundle is received whole or not at all, so a
      // group that has lost either half goes with it:
      //
      //   items with no bundle line above them  -- their quantity is fixed by
      //     that line and nothing else can set it, so they could never be
      //     received
      //   a bundle line with no items under it  -- it would advance the return's
      //     bundle line while putting no stock back
      // =====================================================================
      const referenceId = (value) => {
        if (value && typeof value === "object") return value.id || null;
        return value || null;
      };

      const childrenOf = (row) =>
        Array.isArray(row.children) ? row.children : [];

      const dropIncompleteBundles = (rows) => {
        const drop = new Set();
        let openBundle = null; // { index, bundleId, srId, items }

        const closeBundle = () => {
          if (openBundle && openBundle.items === 0) drop.add(openBundle.index);
          openBundle = null;
        };

        rows.forEach((row, index) => {
          const bundleId = referenceId(row.item_bundle_id);

          if (!bundleId) {
            closeBundle();
            return;
          }

          if (!referenceId(row.material_id)) {
            closeBundle();

            // Already a tree: its items are on it, not beside it.
            if (childrenOf(row).length > 0) return;

            openBundle = {
              index: index,
              bundleId: String(bundleId),
              srId: String(row.sr_id),
              items: 0,
            };
            return;
          }

          if (
            openBundle &&
            openBundle.bundleId === String(bundleId) &&
            openBundle.srId === String(row.sr_id)
          ) {
            openBundle.items += 1;
            return;
          }

          // An item whose bundle line is no longer above it.
          closeBundle();
          drop.add(index);
        });

        closeBundle();

        if (drop.size === 0) return rows;

        console.log("item bundle rows dropped with their bundle", [...drop]);

        return rows.filter((_row, index) => !drop.has(index));
      };

      // The "No" column the user reads, renumbered now that a line is gone. A
      // bundle's items are numbered INSIDE their bundle -- 1, 1-1, 1-2, 2.
      //
      // A subform row is identified by its fm_key, not by where it sits: an
      // item under a bundle is not a row of table_srr at all, so no index
      // reaches it. Position is the fallback for a row without a key yet.
      const numberLines = (rows) => {
        const relabelled = [];

        const relabel = (row, label, path) => {
          if (String(row.line_index == null ? "" : row.line_index) !== label) {
            relabelled.push({ path: `${path}.line_index`, label: label });
          }

          row.line_index = label;
        };

        rows.forEach((row, index) => {
          const path = row.fm_key
            ? `table_srr.${row.fm_key}`
            : `table_srr.${index}`;

          relabel(row, String(index + 1), path);

          childrenOf(row).forEach((child, childIndex) => {
            relabel(
              child,
              `${index + 1}-${childIndex + 1}`,
              child.fm_key
                ? `table_srr.${child.fm_key}`
                : `${path}.children.${childIndex}`,
            );
          });
        });

        return relabelled;
      };

      const kept = dropIncompleteBundles(tableSRR);
      const bundlesChanged = kept.length !== tableSRR.length;
      tableSRR = kept;

      const relabelled = numberLines(tableSRR);

      // A bundle's items carry their own sales order line, and it is not always
      // the bundle's, so the roll-ups are taken over every line in the tree.
      const flat = tableSRR.flatMap((row) => [row, ...childrenOf(row)]);

      let soId = flat.map((srr) => srr.so_id);
      let salesOrderNumber = flat.map((srr) => srr.so_number);
      let gdId = flat.map((srr) => srr.gd_id);
      let goodsDeliveryNumber = flat.map((srr) => srr.gd_number);
      let srId = flat.map((srr) => srr.sr_id);
      let salesReturnNumber = flat.map((srr) => srr.sr_number);

      soId = [...new Set(soId)];
      salesOrderNumber = [...new Set(salesOrderNumber)];
      gdId = [...new Set(gdId)];
      goodsDeliveryNumber = [...new Set(goodsDeliveryNumber)];
      srId = [...new Set(srId)];
      salesReturnNumber = [...new Set(salesReturnNumber)];

      console.log(soId, salesOrderNumber, gdId, goodsDeliveryNumber);
      await this.setData({
        // Rewriting the whole subform is what carries the dropped rows out;
        // when nothing was dropped only the numbers that actually moved are
        // written, each addressed by its own key.
        ...(bundlesChanged
          ? { table_srr: tableSRR }
          : Object.fromEntries(relabelled.map((r) => [r.path, r.label]))),
        so_no_display: salesOrderNumber.join(", "),
        so_id: soId,
        gd_no_display: goodsDeliveryNumber.join(", "),
        gd_id: gdId,
        sr_no_display: salesReturnNumber.join(", "),
        sr_id: srId,
      });
    })();
  }, 50);
})();

// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// A bundle row is not an item: no material, and no stock is received against
// it directly. Its quantity is the number of bundles being received, and every
// item under it follows from that -- their own quantity field is locked, so
// this is the only thing that sets them. A bundle is received whole or not at
// all.
//
// A change on a plain line, or on an item under a bundle, falls straight
// through: there is nothing to spread.
//
// What one bundle contains of an item is worked out from the sales return's own
// figures -- the item's expected quantity over the bundle's -- which is the
// same rate the return was built at. Nothing is read off a per-item running
// total, so a bundle spreads correctly however stale those happen to be.
// ==========================================================================
(async () => {
  const roundQty = (value) => Math.round((parseFloat(value) || 0) * 1000) / 1000;

  const { rowIndex } = arguments[0];
  const rows = this.getValue("table_srr") || [];
  const currentRow = rows[rowIndex] || {};

  // A subform row is identified by its fm_key, not by where it sits: the
  // platform resolves `table_srr.<fm_key>.<field>` to that row, which is the
  // only way to reach an item under a bundle -- it is not a row of table_srr at
  // all. Position is kept as a fallback for a row without a key yet.
  const rowPath = currentRow.fm_key
    ? `table_srr.${currentRow.fm_key}`
    : `table_srr.${rowIndex}`;

  // The tree only exists while the form is open. A saved subform is stored
  // flat -- every item under a bundle is a row of table_srr in its own right,
  // carrying its parent's id in parent_id -- so a bundle just added has its
  // items nested under `children`, while the same bundle reopened for edit has
  // them sitting beside it instead. Both shapes arrive here.
  const isChildOf = (row, parent) => {
    if (
      parent.id != null &&
      parent.id !== "" &&
      row.parent_id != null &&
      row.parent_id !== ""
    ) {
      if (String(row.parent_id) === String(parent.id)) return true;
    }

    if (parent.fm_key != null && row.parent_fm_key != null) {
      if (String(row.parent_fm_key) === String(parent.fm_key)) return true;
    }

    return false;
  };

  // Each item with the path it is written back through: its fm_key, which
  // resolves a row wherever it sits, falling back to its own position when it
  // is a row of table_srr that has no key yet. A nested item with no key has no
  // path of its own -- those are the bundles that have to go across as a whole
  // array instead.
  const resolveBundleChildren = (allRows, parent, parentIndex) => {
    if (Array.isArray(parent.children) && parent.children.length > 0) {
      return parent.children.map((child) => ({
        row: child,
        path: child.fm_key ? `table_srr.${child.fm_key}` : null,
      }));
    }

    const flat = [];

    allRows.forEach((row, index) => {
      if (!row || index === parentIndex) return;
      if (!isChildOf(row, parent)) return;

      flat.push({
        row,
        path: row.fm_key ? `table_srr.${row.fm_key}` : `table_srr.${index}`,
      });
    });

    return flat;
  };

  const bundleChildren = resolveBundleChildren(rows, currentRow, rowIndex);

  // It is the bundle id that says a row is a bundle, but a row holding no
  // material with items under it is one either way. A line with a material is
  // never a bundle, so an ordinary line is untouched by this.
  const isBundleParentRow =
    !currentRow.material_id &&
    (Boolean(currentRow.item_bundle_id) || bundleChildren.length > 0);

  if (!isBundleParentRow) {
    return;
  }

  if (bundleChildren.length === 0) {
    console.log(
      "item bundle line with no items under it, nothing to spread",
      currentRow.item_bundle_id,
    );

    return;
  }

  // How many bundles the return expects. Everything below is a share of that.
  const bundleExpected = roundQty(currentRow.expected_return_qty);

  // A bundle cannot be received past what is still outstanding on its own line.
  const bundleReceivable = roundQty(currentRow.to_receive_qty);

  let effectiveQty = roundQty(
    Math.max(0, parseFloat(currentRow.received_qty) || 0),
  );

  if (effectiveQty > bundleReceivable) {
    effectiveQty = bundleReceivable;

    console.log(
      `Line ${currentRow.line_index}: received quantity adjusted to maximum allowed: ${bundleReceivable}`,
    );
  }

  // What one bundle contains of this item is the rate that produced the item's
  // expected quantity from the bundle's, so receiving N bundles receives N
  // times that.
  const childQty = (child) => {
    if (bundleExpected <= 0) return 0;

    const perBundle =
      (parseFloat(child.expected_return_qty) || 0) / bundleExpected;
    const total = roundQty(perBundle * effectiveQty);

    // Safety net rather than the source of truth: never past what the item
    // itself still has outstanding.
    const receivable = roundQty(child.to_receive_qty);

    return total > receivable ? receivable : total;
  };

  const updates = {};

  if (effectiveQty !== roundQty(currentRow.received_qty)) {
    updates[`${rowPath}.received_qty`] = effectiveQty;
  }

  // A nested row that has not been given a key yet cannot be addressed on its
  // own, so those bundles still go across as one array. An item that is a row
  // of table_srr in its own right always has a path.
  if (bundleChildren.every((child) => child.path)) {
    for (const child of bundleChildren) {
      updates[`${child.path}.received_qty`] = childQty(child.row);
    }
  } else {
    updates[`${rowPath}.children`] = bundleChildren.map((child) => ({
      ...child.row,
      received_qty: childQty(child.row),
    }));
  }

  await this.setData(updates);

  console.log("item bundle line", currentRow.item_bundle_id, {
    receiving: effectiveQty,
    bundlesExpected: bundleExpected,
    children: bundleChildren.map((child) => ({
      material_id: child.row.material_id,
      received_qty: childQty(child.row),
    })),
  });
})();

(async () => {
  const value = arguments[0].value;
  const rowIndex = arguments[0].rowIndex;
  const rows = this.getValue("table_srr") || [];

  // A row is addressed by its fm_key: the platform resolves
  // `table_srr.<fm_key>.<field>` to that row wherever it sits. table_srr is a
  // tree -- an item under an item bundle is not a row of table_srr at all -- so
  // the key is the only thing that reaches it, and a position goes stale the
  // moment a row above it is removed. The event carries the row it fired on;
  // position is the fallback for a row the platform has not keyed yet.
  const rowKey =
    (arguments[0].row && arguments[0].row.fm_key) ||
    (rows[rowIndex] || {}).fm_key ||
    rowIndex;
  const rowPath = `table_srr.${rowKey}`;

  const expectedQty = this.getValue(
    `${rowPath}.expected_return_qty`
  );

  if (value.length > expectedQty) {
    await this.$message.error(
      "Selected serial numbers exceed expected quantity."
    );
    await this.setData({
      [`${rowPath}.select_serial_number`]: value.slice(
        0,
        expectedQty
      ),
    });
    return;
  }

  console.log("value", value);
  console.log("rowPath", rowPath);
  if (value.length > 0) {
    await this.setData({
      [`${rowPath}.received_qty`]: value.length,
    });
  } else {
    await this.setData({
      [`${rowPath}.received_qty`]: 0,
    });
  }
})();

const { setModelKey, newModel, oldModel } = arguments[0];
const oldData = oldModel+'_type';
const newData = newModel+'_type';
setModelKey(oldData, newData);

var params = this.getComponent('srr_no');
const { options } = params;
if(options?.canManualInput) {
  setTimeout(async()=> {
    const getOpData = await this.onDropdownVisible('srr_no_type', true)||[];
    const optionsData = this.getOptionData('srr_no_type') || [];
    let newData = getOpData?.length> 0? getOpData:optionsData;
      const newOptionsData = [{label: 'Manual Input', value: -9999}, ...newData];
      this.setOptionData("srr_no_type", newOptionsData);
  }, 200)
}

const { value } = arguments[0];
this.setData({
  srr_no: ''
});
if(value === -9999) {
   this.disabled('srr_no', false)
} else {
   this.disabled('srr_no', true)
}

if(arguments[0].value) {
  const rows = this.getValue("table_srr") || [];

  // A row is addressed by its fm_key: the platform resolves
  // `table_srr.<fm_key>.<field>` to that row wherever it sits. table_srr is a
  // tree, so the key is the only thing that reaches an item under a bundle.
  const rowKey =
    (arguments[0].row && arguments[0].row.fm_key) ||
    (rows[arguments[0].rowIndex] || {}).fm_key ||
    arguments[0].rowIndex;

  this.setData({[`table_srr.${rowKey}.location_id`]: ''})
  this.refreshFieldOptionData(`table_srr.${rowKey}.location_id`)
}

var params = this.getComponent("srr_no");
const { options } = params;
if (options?.canManualInput && this.isEdit) {
  setTimeout(async () => {
    const getOpData = (await this.onDropdownVisible("srr_no_type", true)) || [];
    const optionsData = this.getOptionData("srr_no_type") || [];
    let newData = getOpData?.length > 0 ? getOpData : optionsData;
    const newOptionsData = [
      { label: "Manual Input", value: -9999 },
      ...newData,
    ];
    this.setOptionData("srr_no_type", newOptionsData);
  }, 200);
}

